/** Adds an ellipsis where a quotation starts or ends mid-sentence. */
function quoted(text: string): string {
  const start = /^[a-z]/.test(text) ? '…' : '';
  const end = /[.!?"”]$/.test(text) ? '' : '…';
  return `“${start}${text}${end}”`;
}

export const coldWarSourceCards: Card[] = SPECS.map((c) => {
  const q = COLD_WAR_QUOTES[c.key];
  if (!q) throw new Error(`Missing Cold War quote ${c.key}`);
  const front = `**Source quote** · ${c.front}`;
  return {
    id: `hist-${c.topic}-${hashString(front)}`,
    subject: 'history',
    topic: c.topic,
    kind: 'quote',
    front,
    back: `${quoted(q.text)}\n\n*${c.origin}*\n\n**Use it:** ${c.use}`,
  };
});
